/* Test-only strict inverse for the two upper/central scouting contexts. */
'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const hash=value=>crypto.createHash('sha256').update(value).digest('hex');
const {decomposeSevenFiveThirdFixedInputSource}=require('./seven-five-third-fixed-input-source-layer.cjs');
const FILE='owned-equipment-planner.js',FIXTURE_SHA256='ea6f81ae51a3376c3199feb6baf92dc79a77852345d5155e3e92859d85298a9f',ENTRY={"beforeBytes":247201,"beforeSHA256":"03c034c48e35c6e9013cfa46dff1eebb2daeae58c56aa3846d35444e8d709715","afterBytes":254453,"approvedAfterSHA256":"bec15796c1ba489588c8ea8fe88ab2c044a7c862de8b48f099b573e413474b19"};
function createUpperCentralScoutingHistoricalProjection(root=path.resolve(__dirname,'../..')){
 const fixedInputEndpoint=decomposeSevenFiveThirdFixedInputSource(root);
 const bytes=fs.readFileSync(path.join(root,'tests/fixtures/upper-central-scouting-approved-source-inverses.json'));assert.equal(hash(bytes),FIXTURE_SHA256,'approved upper-central scouting inverse fixture');const fixture=JSON.parse(bytes);assert.equal(fixture.schemaVersion,1);assert.equal(fixture.beforeSourceHEAD,'78307c4b69f23429aed50b77593df50260fad2bd');assert.deepEqual(Object.keys(fixture.files),[FILE]);assert.deepEqual(fixture.files[FILE],ENTRY);assert.equal(fixture.changes.length,14);for(const r of fixture.changes){assert.equal(r.file,FILE);assert.equal(typeof r.before,'string');assert.equal(typeof r.after,'string');assert.ok(r.before&&r.after&&r.before!==r.after)}
 return function project(file,current){assert.equal(typeof current,'string');current=fixedInputEndpoint(file,current);if(file!==FILE)return current;assert.equal(hash(current),ENTRY.approvedAfterSHA256,'exact approved current upper-central source');assert.equal(Buffer.byteLength(current),ENTRY.afterBytes);let restored=current;for(const r of fixture.changes.slice().reverse()){assert.equal(restored.split(r.after).length,2,'unique upper-central inverse anchor');restored=restored.replace(r.after,r.before)}assert.equal(hash(restored),ENTRY.beforeSHA256);assert.equal(Buffer.byteLength(restored),ENTRY.beforeBytes);let replay=restored;for(const r of fixture.changes){assert.equal(replay.split(r.before).length,2,'unique upper-central replay anchor');replay=replay.replace(r.before,r.after)}assert.equal(replay===current,true,'whole source inverse/replay exact');return restored;};
}
// Exact already-decomposed preceding bytes may pass into an older historical
// layer. Every other owned source must satisfy the strict current inverse.
function decomposeUpperCentralScoutingSource(root=path.resolve(__dirname,'../..')){const project=createUpperCentralScoutingHistoricalProjection(root);return function(file,current){assert.equal(typeof current,'string');if(file===FILE&&hash(current)===ENTRY.beforeSHA256){assert.equal(Buffer.byteLength(current),ENTRY.beforeBytes);return current}return project(file,current)};}
module.exports={createUpperCentralScoutingHistoricalProjection,decomposeUpperCentralScoutingSource};
